begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api,cuevo_worker,authenticated;set local search_path=extensions,pg_catalog;select no_plan();
insert into app.entitlements(school_id,code,enabled,effective_from)select id,'community',true,'2026-09-01'from app.schools on conflict(school_id,code)do update set enabled=true;
create temporary table community_ids(room_id uuid,post_id uuid,report_id uuid,member_change_id uuid,member_event_id uuid);grant select,insert,update on community_ids to cuevo_api;grant select on community_ids to authenticated,cuevo_worker;
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
insert into community_ids(room_id)select(internal.community_command('room.create',null,'{"classId":"30000000-0000-4000-8000-000000000001","name":"Teacher-led safety group","type":"GROUP","memberIds":["20000000-0000-4000-8000-000000000012"]}','community-room-golden-001',repeat('a',64),'community-request')->>'id')::uuid;
update community_ids set member_change_id=(internal.community_command('member.configure',room_id,'{"actorId":"20000000-0000-4000-8000-000000000018","status":"active","confirmAccessChange":true}','community-member-change-001',repeat('a',64),'community-request')->>'id')::uuid;
select internal.community_command('member.configure',(select room_id from community_ids),'{"actorId":"20000000-0000-4000-8000-000000000018","status":"revoked","confirmAccessChange":true}','community-member-revoke-001',repeat('b',64),'community-request');
reset role;
update community_ids set member_event_id=(select id from internal.outbox_events where school_id='10000000-0000-4000-8000-000000000001'and entity_id=community_ids.member_change_id and type='community.changed');
select ok(exists(select 1 from app.community_member_changes c where c.id=(select member_change_id from community_ids)and c.status='active'),'historical membership change remains immutable after current revocation');
update internal.outbox_events set state='PROCESSING',lease_token='86000000-0000-4000-8000-000000000081',lease_until=clock_timestamp()+interval'60 seconds'where id=(select member_event_id from community_ids);
set local role cuevo_worker;select lives_ok($$select internal.process_community_event((select member_event_id from community_ids),'86000000-0000-4000-8000-000000000081')$$,'delayed membership invalidation resolves immutable historical source');reset role;
set local role cuevo_api;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000018',true);
select throws_ok($$select internal.community_list('posts',(select room_id from community_ids),'{"limit":25}')$$,'42501',null,'peer outside teacher-led group denied');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
update community_ids set post_id=(internal.community_command('post.create',room_id,'{"body":"School discussion","replyToId":null}','community-post-golden-001',repeat('b',64),'community-request')->>'id')::uuid;
select is((select internal.community_command('post.create',room_id,'{"body":"School discussion","replyToId":null}','community-post-golden-001',repeat('b',64),'community-replay')->>'id'from community_ids),(select post_id::text from community_ids),'post replay returns one source');
update community_ids set report_id=(internal.community_command('report.create',post_id,'{"reason":"Staff review requested"}','community-report-golden-001',repeat('c',64),'community-request')->>'id')::uuid;
select throws_ok($$select internal.community_list('reports',(select room_id from community_ids),'{"limit":25}')$$,'42501',null,'student cannot read private reporter queue');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select is(jsonb_array_length(internal.community_list('reports',(select room_id from community_ids),'{"limit":25}')->'items'),1,'room owner has staff report queue');
select internal.community_command('post.moderate',(select post_id from community_ids),'{"action":"HIDE","reason":"Reviewed by teacher","confirmModeration":true}','community-hide-golden-001',repeat('d',64),'community-request');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select ok((internal.community_list('posts',(select room_id from community_ids),'{"limit":25}')->'items'->0->'body')='null'::jsonb,'hidden post body excluded');
select throws_ok($$select internal.community_command('post.create',(select room_id from community_ids),'{"body":"School discussion","replyToId":null}','community-post-golden-001',repeat('b',64),'community-hidden-replay')$$,'42501',null,'hidden post cannot leak body through stored command replay');
select throws_ok($$select internal.community_command('reaction.configure',(select post_id from community_ids),'{"reaction":"HELPFUL","active":true}','community-hidden-react-001',repeat('e',64),'community-request')$$,'42501',null,'hidden reaction denied');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.community_command('room.restrict',(select room_id from community_ids),'{"actorId":"20000000-0000-4000-8000-000000000012","restriction":"MUTED","reason":"Teacher restricted posting","confirmModeration":true}','community-mute-golden-001',repeat('f',64),'community-request');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select throws_ok($$select internal.community_command('post.create',(select room_id from community_ids),'{"body":"Muted bypass","replyToId":null}','community-muted-post-001',repeat('a',64),'community-request')$$,'42501',null,'muted student cannot create post');
select throws_ok($$select internal.community_command('post.create',(select room_id from community_ids),'{"body":"School discussion","replyToId":null}','community-post-golden-001',repeat('b',64),'community-replay')$$,'42501',null,'current restriction checked before stored replay');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.community_command('room.restrict',(select room_id from community_ids),'{"actorId":"20000000-0000-4000-8000-000000000012","restriction":"NONE","reason":"Teacher restored posting","confirmModeration":true}','community-unmute-golden-001',repeat('f',64),'community-request');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
reset role;
create function pg_temp.community_spam_probe()returns boolean language plpgsql as $$declare accepted integer:=0;blocked integer:=0;n integer;begin
 for n in 1..11 loop
  begin perform internal.community_command('post.create',(select room_id from community_ids),jsonb_build_object('body','Bounded spam fixture '||n,'replyToId',null),'community-spam-golden-'||n,repeat('a',64),'community-request');accepted:=accepted+1;
  exception when sqlstate 'P0003'then blocked:=blocked+1;end;
 end loop;
 return accepted<=10 and blocked>=1;
end$$;
grant execute on function pg_temp.community_spam_probe()to cuevo_api;
set local role cuevo_api;
select ok(pg_temp.community_spam_probe(),'committed actor actions are bounded against spam');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is(jsonb_array_length(internal.community_list('rooms',null,'{"limit":25}')->'items'),0,'parent receives no raw discussion rooms');
reset role;update app.classes set status='archived'where school_id='10000000-0000-4000-8000-000000000001'and id='30000000-0000-4000-8000-000000000001';
select is("authorization".community_announcement('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001',true,'20000000-0000-4000-8000-000000000072'),false,'parent class announcement denied after class archival');
update app.classes set status='active'where school_id='10000000-0000-4000-8000-000000000001'and id='30000000-0000-4000-8000-000000000001';
set local role cuevo_api;
reset role;
select is((select count(*)from app.community_posts where id=(select post_id from community_ids)),1::bigint,'duplicate key creates one immutable post');
select is((select count(*)from internal.audit_events where action='community.report.create'and entity_id=(select report_id from community_ids)),1::bigint,'report creates auditable staff escalation');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_roles r on r.rolname in('anon','authenticated','service_role','cuevo_api','cuevo_worker')where n.nspname='app'and c.relname like'community_%'and has_table_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE')),'raw community records private from runtime and Data API');
select ok(exists(select 1 from pg_policies where schemaname='realtime'and tablename='messages'and policyname='cuevo_clients_cannot_send'and permissive='RESTRICTIVE'and cmd='INSERT'),'explicit restrictive RLS denies client Broadcast/Presence publishing');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000012","session_id":"99999999-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is("authorization".community_realtime_topic('cuevo:10000000-0000-4000-8000-000000000001:room:'||(select room_id::text from community_ids)),false,'private channel rejects absent or revoked Auth session');
select throws_ok($$insert into realtime.messages(topic,extension,payload,event,private)values('cuevo:10000000-0000-4000-8000-000000000001:room:00000000-0000-4000-8000-000000000001','broadcast','{}','invalidate',true)$$,'42501',null,'authenticated client cannot insert a private Broadcast message');
reset role;select*from finish();rollback;
